// One item per client + current/previous date windows (IST)
const c = $input.first().json;
let clients;
try { clients = JSON.parse(c.clients); } catch (e) { throw new Error('Config → clients must be a valid JSON array'); }
const now = DateTime.now().setZone('Asia/Kolkata');
let curStart, curEnd, prevStart, prevEnd, label;
if (String(c.report_frequency).toLowerCase() === 'weekly') {
  curEnd = now.minus({ days: 1 }).endOf('day');          // last 7 full days
  curStart = curEnd.minus({ days: 6 }).startOf('day');
  prevEnd = curStart.minus({ days: 1 });
  prevStart = prevEnd.minus({ days: 6 });
  label = `${curStart.toFormat('dd LLL')} – ${curEnd.toFormat('dd LLL yyyy')}`;
} else {
  const lm = now.minus({ months: 1 });
  curStart = lm.startOf('month'); curEnd = lm.endOf('month');
  prevStart = lm.minus({ months: 1 }).startOf('month'); prevEnd = lm.minus({ months: 1 }).endOf('month');
  label = curStart.toFormat('LLLL yyyy');
}
const d = x => x.toISODate();
const { clients: _drop, ...rest } = c;
return clients.map(cl => ({ json: {
  ...rest,
  client_name: cl.client,
  contact_name: cl.contact_name || 'there',
  client_email: cl.email,
  ga4_property_id: String(cl.ga4_property_id || '').replace(/^properties\//, ''),
  google_ads_customer_id: String(cl.google_ads_customer_id || '').replace(/-/g, ''),
  meta_ad_account_id: cl.meta_ad_account_id ? (String(cl.meta_ad_account_id).startsWith('act_') ? cl.meta_ad_account_id : 'act_' + cl.meta_ad_account_id) : '',
  cur_start: d(curStart), cur_end: d(curEnd), prev_start: d(prevStart), prev_end: d(prevEnd),
  period_label: label,
  meta_time_ranges: JSON.stringify([{ since: d(curStart), until: d(curEnd) }, { since: d(prevStart), until: d(prevEnd) }])
}}));

// Normalize GA4 + Google Ads + Meta into one KPI model with period-over-period deltas
const c = $('Split Clients1').item.json;
const ga4Resp = $('GA4 Run Reports1').item.json || {};
const gadsResp = $('Google Ads Campaign Report1').item.json || {};
const metaResp = $json || {};
const n = v => Number(v) || 0;
const pct = (a, b) => (b > 0 ? +(((a - b) / b) * 100).toFixed(1) : null);
const safeDiv = (a, b) => (b > 0 ? a / b : null);
const errMsg = r => (r && r.error ? (r.error.message || JSON.stringify(r.error)).slice(0, 200) : null);

// ---------- GA4 ----------
let ga4 = { connected: !!c.ga4_property_id, error: c.ga4_property_id ? errMsg(ga4Resp) : null };
if (ga4.connected && !ga4.error && Array.isArray(ga4Resp.reports)) {
  const [tot, ch] = ga4Resp.reports;
  const names = (tot.metricHeaders || []).map(h => h.name);
  const pick = label => {
    const row = (tot.rows || []).find(r => (r.dimensionValues || [])[0]?.value === label) || { metricValues: [] };
    return Object.fromEntries(names.map((nm, i) => [nm, n(row.metricValues[i]?.value)]));
  };
  const cur = pick('current'), prev = pick('previous');
  ga4.current = cur; ga4.previous = prev;
  ga4.delta = Object.fromEntries(names.map(nm => [nm, pct(cur[nm], prev[nm])]));
  ga4.conv_rate = +(safeDiv(cur.keyEvents, cur.sessions) * 100 || 0).toFixed(2);
  ga4.channels = (ch?.rows || []).map(r => ({
    channel: r.dimensionValues[0].value, sessions: n(r.metricValues[0].value),
    key_events: n(r.metricValues[1].value), revenue: n(r.metricValues[2].value)
  }));
}

// ---------- Ads helper ----------
const summarize = rows => {
  const t = rows.reduce((s, r) => ({ spend: s.spend + r.spend, impressions: s.impressions + r.impressions, clicks: s.clicks + r.clicks, conversions: s.conversions + r.conversions, revenue: s.revenue + r.revenue }), { spend: 0, impressions: 0, clicks: 0, conversions: 0, revenue: 0 });
  t.ctr = +((safeDiv(t.clicks, t.impressions) || 0) * 100).toFixed(2);
  t.cpc = +(safeDiv(t.spend, t.clicks) || 0).toFixed(2);
  t.cpa = t.conversions ? +(t.spend / t.conversions).toFixed(0) : null;
  t.roas = t.spend ? +(t.revenue / t.spend).toFixed(2) : null;
  t.conversions = +t.conversions.toFixed(1);
  return t;
};
const deltas = (a, b) => Object.fromEntries(['spend', 'impressions', 'clicks', 'conversions', 'revenue', 'ctr', 'cpc', 'cpa', 'roas'].map(k => [k, pct(n(a[k]), n(b[k]))]));
const topCampaigns = rows => {
  const m = {};
  for (const r of rows) { (m[r.campaign] ||= []).push(r); }
  return Object.entries(m).map(([campaign, rs]) => ({ campaign, ...summarize(rs) })).sort((a, b) => b.spend - a.spend).slice(0, 5);
};

// ---------- Google Ads ----------
let gads = { connected: !!c.google_ads_customer_id, error: c.google_ads_customer_id ? errMsg(gadsResp) : null };
if (gads.connected && !gads.error) {
  const results = Array.isArray(gadsResp) ? gadsResp.flatMap(b => b.results || []) : (gadsResp.results || []);
  const rows = results.map(r => ({
    campaign: r.campaign?.name || 'Unknown', date: r.segments?.date,
    spend: n(r.metrics?.costMicros) / 1e6, impressions: n(r.metrics?.impressions), clicks: n(r.metrics?.clicks),
    conversions: n(r.metrics?.conversions), revenue: n(r.metrics?.conversionsValue)
  }));
  const cur = rows.filter(r => r.date >= c.cur_start && r.date <= c.cur_end);
  const prev = rows.filter(r => r.date >= c.prev_start && r.date <= c.prev_end);
  gads.current = summarize(cur); gads.previous = summarize(prev);
  gads.delta = deltas(gads.current, gads.previous);
  gads.top_campaigns = topCampaigns(cur);
}

// ---------- Meta ----------
let meta = { connected: !!c.meta_ad_account_id, error: c.meta_ad_account_id ? errMsg(metaResp) : null };
if (meta.connected && !meta.error) {
  const types = String(c.meta_result_action_types).split(',').map(s => s.trim());
  const sumActs = arr => (arr || []).filter(a => types.includes(a.action_type)).reduce((s, a) => s + n(a.value), 0);
  const rows = (metaResp.data || []).map(r => ({
    campaign: r.campaign_name || 'Unknown', date: r.date_start,
    spend: n(r.spend), impressions: n(r.impressions), clicks: n(r.clicks),
    conversions: sumActs(r.actions), revenue: sumActs(r.action_values)
  }));
  const cur = rows.filter(r => r.date === c.cur_start);
  const prev = rows.filter(r => r.date === c.prev_start);
  meta.current = summarize(cur); meta.previous = summarize(prev);
  meta.delta = deltas(meta.current, meta.previous);
  meta.top_campaigns = topCampaigns(cur);
}

// ---------- Blended ----------
const paid = [gads, meta].filter(x => x.current);
const blendCur = summarize(paid.map(x => ({ ...x.current })));
const blendPrev = summarize(paid.map(x => ({ ...x.previous })));
const blended = { current: blendCur, previous: blendPrev, delta: deltas(blendCur, blendPrev) };

return { json: { ...c, ga4, gads, meta, blended } };

