// Build branded A4 HTML report + client email
const d = $('Aggregate KPIs1').item.json;
let ai = $json.message?.content ?? $json.content ?? {};
if (typeof ai === 'string') { try { ai = JSON.parse(ai.replace(/```json|```/g, '').trim()); } catch (e) { ai = {}; } }
const cur = d.currency_symbol, brand = d.brand_color || '#4F46E5';
const esc = s => String(s ?? '').replace(/[&<>"]/g, m => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[m]));
const num = v => (v === null || v === undefined ? '—' : Math.round(v).toLocaleString('en-IN'));
const money = v => (v === null || v === undefined ? '—' : cur + Math.round(v).toLocaleString('en-IN'));
const dec = (v, k = 2) => (v === null || v === undefined ? '—' : Number(v).toFixed(k));
// lowerIsBetter flips colour for cost metrics
const delta = (v, lowerIsBetter = false) => {
  if (v === null || v === undefined) return '<span class="d n">—</span>';
  const good = lowerIsBetter ? v < 0 : v > 0;
  return `<span class="d ${v === 0 ? 'n' : good ? 'g' : 'b'}">${v > 0 ? '▲' : v < 0 ? '▼' : '•'} ${Math.abs(v).toFixed(1)}%</span>`;
};
const card = (label, value, dv, lib) => `<div class="card"><div class="lbl">${label}</div><div class="val">${value}</div>${delta(dv, lib)}</div>`;
const list = arr => (Array.isArray(arr) && arr.length ? `<ul>${arr.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '<p class="muted">—</p>');
const campTable = rows => `<table><thead><tr><th>Campaign</th><th>Spend</th><th>Clicks</th><th>CTR</th><th>Conv.</th><th>CPA</th><th>ROAS</th></tr></thead><tbody>${
  rows.map(r => `<tr><td>${esc(r.campaign)}</td><td>${money(r.spend)}</td><td>${num(r.clicks)}</td><td>${dec(r.ctr)}%</td><td>${dec(r.conversions, 1)}</td><td>${money(r.cpa)}</td><td>${r.roas === null ? '—' : dec(r.roas) + 'x'}</td></tr>`).join('')}</tbody></table>`;
const notConnected = (x, name) => (!x.connected ? `<p class="muted">${name} is not connected for this client.</p>` : x.error ? `<p class="err">${name} data unavailable: ${esc(x.error)}</p>` : '');

const adsSection = (x, title) => {
  const nc = notConnected(x, title);
  if (nc) return `<section><h2>${title}</h2>${nc}</section>`;
  const c = x.current, dl = x.delta;
  return `<section><h2>${title}</h2><div class="grid">
    ${card('Spend', money(c.spend), dl.spend, false)}${card('Clicks', num(c.clicks), dl.clicks)}
    ${card('CTR', dec(c.ctr) + '%', dl.ctr)}${card('Conversions', dec(c.conversions, 1), dl.conversions)}
    ${card('Cost / Conv.', money(c.cpa), dl.cpa, true)}${card('ROAS', c.roas === null ? '—' : dec(c.roas) + 'x', dl.roas)}
  </div>${x.top_campaigns?.length ? '<h3>Top campaigns</h3>' + campTable(x.top_campaigns) : ''}</section>`;
};

let ga4Html;
const g = d.ga4;
const nc = notConnected(g, 'Google Analytics 4');
if (nc) ga4Html = `<section><h2>Website (Google Analytics 4)</h2>${nc}</section>`;
else ga4Html = `<section><h2>Website (Google Analytics 4)</h2><div class="grid">
  ${card('Sessions', num(g.current.sessions), g.delta.sessions)}${card('Users', num(g.current.totalUsers), g.delta.totalUsers)}
  ${card('New users', num(g.current.newUsers), g.delta.newUsers)}${card('Key events', num(g.current.keyEvents), g.delta.keyEvents)}
  ${card('Engagement rate', dec(g.current.engagementRate * 100, 1) + '%', g.delta.engagementRate)}${card('Revenue', money(g.current.totalRevenue), g.delta.totalRevenue)}
  </div><h3>Traffic by channel</h3><table><thead><tr><th>Channel</th><th>Sessions</th><th>Key events</th><th>Revenue</th></tr></thead><tbody>${
  g.channels.map(r => `<tr><td>${esc(r.channel)}</td><td>${num(r.sessions)}</td><td>${num(r.key_events)}</td><td>${money(r.revenue)}</td></tr>`).join('')}</tbody></table></section>`;

const b = d.blended;
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${esc(d.client_name)} – ${esc(d.period_label)} Report</title>
<style>
@page { size: A4; margin: 14mm 12mm; }
* { box-sizing: border-box; }
body { font-family: 'Helvetica Neue', Arial, sans-serif; color: #1f2937; font-size: 11px; line-height: 1.5; margin: 0; }
.hero { background: ${brand}; color: #fff; padding: 22px 24px; border-radius: 10px; }
.hero .ag { opacity: .85; font-size: 11px; letter-spacing: .08em; text-transform: uppercase; }
.hero h1 { margin: 4px 0 2px; font-size: 24px; }
.hero .per { opacity: .9; }
.headline { font-size: 15px; font-weight: 600; margin: 18px 0 6px; color: ${brand}; }
section { margin-top: 18px; page-break-inside: avoid; }
h2 { font-size: 14px; border-bottom: 2px solid ${brand}; padding-bottom: 4px; margin: 0 0 10px; }
h3 { font-size: 12px; margin: 12px 0 6px; color: #374151; }
.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
.card { border: 1px solid #e5e7eb; border-radius: 8px; padding: 10px 12px; background: #fafafa; }
.lbl { font-size: 9.5px; color: #6b7280; text-transform: uppercase; letter-spacing: .05em; }
.val { font-size: 18px; font-weight: 700; margin: 2px 0; }
.d { font-size: 10px; font-weight: 600; } .g { color: #059669; } .b { color: #dc2626; } .n { color: #9ca3af; }
table { width: 100%; border-collapse: collapse; font-size: 10px; }
th { background: #f3f4f6; text-align: left; padding: 6px; font-weight: 600; }
td { padding: 6px; border-bottom: 1px solid #f0f0f0; }
.cols { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.box { border-radius: 8px; padding: 10px 14px; }
.win { background: #ecfdf5; } .con { background: #fef2f2; } .rec { background: #eef2ff; }
.box h3 { margin-top: 0; } ul { margin: 4px 0; padding-left: 16px; }
.muted { color: #9ca3af; } .err { color: #dc2626; }
.foot { margin-top: 22px; font-size: 9px; color: #9ca3af; text-align: center; }
</style></head><body>
<div class="hero"><div class="ag">${esc(d.agency_name)} · Performance Report</div><h1>${esc(d.client_name)}</h1>
<div class="per">${esc(d.period_label)} · compared with previous period (${esc(d.prev_start)} to ${esc(d.prev_end)})</div></div>
<div class="headline">${esc(ai.headline || 'Performance overview')}</div>
<p>${esc(ai.executive_summary || '')}</p>
<section><h2>Paid media overview (Google Ads + Meta)</h2><div class="grid">
${card('Total ad spend', money(b.current.spend), b.delta.spend, false)}${card('Total conversions', dec(b.current.conversions, 1), b.delta.conversions)}
${card('Blended cost / conv.', money(b.current.cpa), b.delta.cpa, true)}${card('Clicks', num(b.current.clicks), b.delta.clicks)}
${card('Attributed revenue', money(b.current.revenue), b.delta.revenue)}${card('Blended ROAS', b.current.roas === null ? '—' : dec(b.current.roas) + 'x', b.delta.roas)}
</div></section>
${ga4Html}
${adsSection(d.gads, 'Google Ads')}
${adsSection(d.meta, 'Meta Ads (Facebook & Instagram)')}
<section><div class="cols">
<div class="box win"><h3>✅ What went well</h3>${list(ai.wins)}</div>
<div class="box con"><h3>⚠️ What needs attention</h3>${list(ai.concerns)}</div></div>
<div class="box rec" style="margin-top:12px"><h3>🎯 Recommendations for next period</h3>${list(ai.recommendations)}
${ai.next_period_focus ? `<p><strong>Focus:</strong> ${esc(ai.next_period_focus)}</p>` : ''}</div></section>
<div class="foot">Prepared by ${esc(d.agency_name)} · Data: Google Analytics 4, Google Ads, Meta Ads Manager · Platform-reported conversions may overlap across channels.</div>
</body></html>`;

const fileName = `${d.client_name.replace(/[^a-z0-9]+/gi, '-')}-Report-${d.cur_start}.pdf`;
const emailHtml = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1f2937;line-height:1.6">
<p>Hi ${esc(d.contact_name)},</p>
<p>Your <strong>${esc(d.period_label)}</strong> performance report is ready.</p>
<p style="font-size:15px;color:${brand}"><strong>${esc(ai.headline || '')}</strong></p>
<p>${esc(ai.email_summary || ai.executive_summary || '')}</p>
<p><strong>At a glance:</strong><br>
Ad spend: ${money(b.current.spend)} · Conversions: ${dec(b.current.conversions, 1)} · Cost per conversion: ${money(b.current.cpa)}${b.current.roas ? ` · ROAS: ${dec(b.current.roas)}x` : ''}</p>
<p>The full report (PDF) is attached. Happy to walk you through it on a quick call.</p>
<p>Best regards,<br>${esc(d.agency_name)}</p></div>`;

return { json: {
  ...d,
  ai_headline: ai.headline || '',
  report_html: html,
  pdf_file_name: fileName,
  email_subject: `${d.client_name} – ${d.period_label} Performance Report${ai.headline ? ': ' + ai.headline : ''}`.slice(0, 150),
  email_html: emailHtml
}};

// Prepare GHL contact + email payloads (after PDF upload)
const d = $('Build HTML Report1').item.json;
const fileId = $('Upload PDF to Drive1').item.json.id;
const pdfUrl = `https://drive.google.com/uc?export=download&id=${fileId}`;
const viewUrl = `https://drive.google.com/file/d/${fileId}/view`;
const [firstName, ...rest] = String(d.contact_name || '').split(' ');
return { json: {
  client_name: d.client_name, client_email: d.client_email, period_label: d.period_label,
  pdf_url: pdfUrl, pdf_view_url: viewUrl,
  ghl_contact_payload: {
    locationId: d.ghl_location_id, email: d.client_email, firstName: firstName || undefined,
    lastName: rest.join(' ') || undefined, companyName: d.client_name, tags: ['client-report-recipient']
  },
  email_subject: d.email_subject,
  email_html: d.email_html.replace('The full report (PDF) is attached.', `The full report (PDF) is attached — you can also <a href="${viewUrl}">view it online here</a>.`),
  email_from: d.ghl_email_from
}};
